///         Adds existing run-persistent mod piles to <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.Piles" />.
///     </para>
///     <para xml:lang="zh-CN">将已有的局内持久模组牌堆加入 <see cref="P:MegaCrit.Sts2.Core.Entities.Players.Player.Piles" />。</para>
/// </summary>
internal sealed class ModCardPilePlayerPilesPatch : IPatchMethod
{
	public static string PatchId => "ritsulib_player_piles_run_persistent_mod_piles";

	public static string Description => "Append run-persistent mod card piles to Player.Piles";

	public static bool IsCritical => false;

	public static ModPatchTarget[] GetTargets()
	{
		return new ModPatchTarget[1]
		{
			new ModPatchTarget(typeof(Player), "Piles", (MethodType)1)
		};
	}

	public static void Postfix(Player __instance, ref IEnumerable<CardPile> __result)
	{
		IReadOnlyCollection<ModCardPile> runPiles = ModCardPileStorage.GetRunPiles(__instance);
