using System.Collections.Immutable;
using System.Reflection;
using CombatSolver.Engine.Common;
using HarmonyLib;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Enchantments;
using STS2RitsuLib.Combat.Healing;

namespace CombatSolver;

// This proof covers the direct card-value recalculation call, not the remaining
// CombatStateChanged audience, future generation closure or a whole HP bound.
internal static class TaskCardValueNotificationProof
{
    private static readonly Guid GameMvid=new("8a76776c-0ce1-4d4f-90bd-8cce653dad8e");
    private static readonly Guid RitsuMvid=new("f7f18a36-8ebb-4db2-b1ea-7bd340579646");
    private const BindingFlags Fields=BindingFlags.Static|BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.DeclaredOnly;
    private static readonly Type[] EmptySourceTypes=[typeof(Slither),typeof(Inky),typeof(Instinct)];
    internal sealed record Result(bool Certified,string? Rejection,int Cards,int EnchantedCards,
        ImmutableArray<string> EmptyBindings,bool FutureBindingsChecked);

    internal static Result Capture(PlayerCombatState pcs)
    {
        Result Refuse(string reason)=>new(false,reason,0,0,[],false);
        if(typeof(CardModel).Module.ModuleVersionId!=GameMvid)return Refuse("native-version");
        FieldInfo Field(Type type,string name)=>type.GetField(name,Fields)
            ??throw new PredictionUnsupportedException("Recalculation field contract changed: "+type.FullName+"."+name);
        MethodInfo Getter(Type type,string name)=>type.GetProperty(name,Fields)?.GetMethod
            ??throw new PredictionUnsupportedException("Recalculation getter contract changed: "+type.FullName+"."+name);
        MethodInfo Method(Type type,string name)=>type.GetMethod(name,Fields,null,Type.EmptyTypes,null)
            ??throw new PredictionUnsupportedException("Recalculation method contract changed: "+type.FullName+"."+name);
        bool HasPatch(MethodBase method)
        {
            Patches? p=Harmony.GetPatchInfo(method);
            return p is not null&&p.Prefixes.Count+p.Postfixes.Count+p.Transpilers.Count+p.Finalizers.Count!=0;
        }
        var methods=new[]{Method(typeof(PlayerCombatState),"RecalculateCardValues"),Getter(typeof(PlayerCombatState),"AllCards"),
            Getter(typeof(CardPile),"Cards"),Getter(typeof(CardModel),"Enchantment")};
        foreach(var method in methods)if(HasPatch(method))return Refuse("patch:"+method.DeclaringType?.FullName+"."+method.Name);
        if(methods[2].IsVirtual||methods[3].IsVirtual)return Refuse("virtual-getter-contract");
        foreach(var nested in typeof(PlayerCombatState).GetNestedTypes(BindingFlags.Public|BindingFlags.NonPublic))
            foreach(var method in nested.GetMethods(Fields))
                if(HasPatch(method))return Refuse("patch:pcs-enumeration-helper:"+method.Name);
        if(Harmony.GetAllPatchedMethods().Any(m=>m.Module.Assembly==typeof(Enumerable).Assembly))
            return Refuse("patch:linq-dependency");
        MethodInfo allPiles=Getter(typeof(PlayerCombatState),"AllPiles");
        Patches? patches=Harmony.GetPatchInfo(allPiles);
        if(patches is not null&&patches.Prefixes.Count+patches.Postfixes.Count+patches.Transpilers.Count+patches.Finalizers.Count!=0)
        {
            if(typeof(HealHook).Module.ModuleVersionId!=RitsuMvid)return Refuse("ritsu-version");
            Type type=typeof(HealHook).Assembly.GetType("STS2RitsuLib.CardPiles.Patches.ModCardPileAllPilesPatch",true)!;
            MethodInfo postfix=type.GetMethod("Postfix",Fields,null,[typeof(PlayerCombatState),typeof(IReadOnlyList<CardPile>).MakeByRefType()],null)!;
            if(patches.Prefixes.Count!=0||patches.Postfixes.Count!=1||patches.Postfixes[0].PatchMethod!=postfix
                ||patches.Transpilers.Count+patches.Finalizers.Count!=0)return Refuse("patch:all-piles-combination");
            Type registry=typeof(HealHook).Assembly.GetType("STS2RitsuLib.CardPiles.ModCardPileRegistry",true)!;
            if(HasPatch(postfix)||HasPatch(Method(registry,"GetCombatDefinitionsSnapshot")))return Refuse("patch:ritsu-pile-forwarder");
            var gate=Field(registry,"SyncRoot").GetValue(null) as Lock
                ??throw new PredictionUnsupportedException("Unknown pile registration lock.");
            using(gate.EnterScope())
            {
                if(Field(registry,"<IsFrozen>k__BackingField").GetValue(null) is not true)return Refuse("pile-registration-not-frozen");
                object snapshot=Field(registry,"_combatDefinitionsSnapshot").GetValue(null)!;
                if(snapshot is not Array entries||snapshot.GetType()!=Field(registry,"_combatDefinitionsSnapshot").FieldType)
                    return Refuse("unknown-combat-pile-snapshot");
                if(entries.Length!=0)return Refuse("extra-combat-pile-definitions");
            }
        }
        CardPile[] piles=new[]{"Hand","DrawPile","DiscardPile","ExhaustPile","PlayPile"}
            .Select(name=>Field(typeof(PlayerCombatState),"<"+name+">k__BackingField").GetValue(pcs) as CardPile
                ??throw new PredictionUnsupportedException("Missing native pile.")).ToArray();
        object? cached=Field(typeof(PlayerCombatState),"_piles").GetValue(pcs);
        if(cached is not null&&(cached.GetType()!=typeof(CardPile[])||!((CardPile[])cached).SequenceEqual(piles)))
            return Refuse("non-native-pile-cache");
        var cards=new List<CardModel>();
        foreach(var pile in piles)
        {
            if(pile.GetType()!=typeof(CardPile))return Refuse("unknown-pile-instance");
            object value=Field(typeof(CardPile),"_cards").GetValue(pile)!;
            if(value.GetType()!=typeof(List<CardModel>))return Refuse("unknown-card-list");
            cards.AddRange((List<CardModel>)value);
        }
        if(cards.Distinct(ReferenceEqualityComparer.Instance).Count()!=cards.Count)return Refuse("duplicate-card-ownership");
        MethodInfo empty=Method(typeof(EnchantmentModel),"RecalculateValues");
        MethodBody? body=empty.GetMethodBody();
        if(!empty.IsVirtual||body is null||body.LocalVariables.Count!=0||body.ExceptionHandlingClauses.Count!=0
            ||!body.GetILAsByteArray()!.SequenceEqual(new byte[]{0x2a}))return Refuse("unknown-empty-recalculate-body");
        if(HasPatch(empty))return Refuse("patch:base-recalculate");
        var bindings=ImmutableArray.CreateBuilder<string>();
        foreach(Type type in EmptySourceTypes)
        {
            MethodInfo? binding=type.GetMethod("RecalculateValues",BindingFlags.Instance|BindingFlags.Public);
            if(binding is null||binding.Module!=empty.Module||binding.MetadataToken!=empty.MetadataToken
                ||binding.DeclaringType!=typeof(EnchantmentModel))return Refuse("future-enchantment-binding:"+type.FullName);
            bindings.Add(type.FullName+"->"+empty.DeclaringType!.FullName);
        }
        int enchanted=0;
        foreach(CardModel card in cards)
        {
            object? value=Field(typeof(CardModel),"<Enchantment>k__BackingField").GetValue(card);
            if(value is null)continue;
            if(value is not EnchantmentModel enchantment||!EmptySourceTypes.Contains(enchantment.GetType()))
                return Refuse("unreviewed-enchantment:"+value.GetType().FullName);
            enchanted++;
        }
        return new(true,null,cards.Count,enchanted,bindings.ToImmutable(),true);
    }
}

