                    if (System.Environment.TickCount64 >= restoreDeadline)
                    {
                        throw new InvalidOperationException(
                            $"自动执行后游戏速度为 {SaveManager.Instance.PrefsSave.FastMode}，" +
                            $"5 秒内没有恢复为 {expectedFastMode}。");
