using System.Reflection;
using System.Text.Json;
using Godot;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Enchantments;
using MegaCrit.Sts2.Core.Nodes;
using STS2RitsuLib.Combat.Healing;

namespace CombatSolver;
internal sealed partial class UnattendedTestRunner
{
    private static int _taskCardValueUnknownCalls;
    private static void TaskCardValueUnknownPrefix()=>_taskCardValueUnknownCalls++;

    private async Task AssertTaskCardValueNotificationProofAsync(CombatState live,Player player)
    {
        SetStage("task_card_value_notification_proof");
        await ClearPlayerPilesAsync(player);
        foreach(var item in new[]{("Hand","SLITHER"),("Draw","INKY"),("Discard","INSTINCT"),("Exhaust","")})
            await InjectCardAsync(live,player,new(){CardId="STRIKE_DEFECT",Pile=item.Item1,EnchantmentId=item.Item2,EnchantmentAmount=1});
        var playCard=live.CreateCard(ModelDb.AllCards.Single(c=>c.Id.Entry=="STRIKE_DEFECT"),player);
        player.PlayerCombatState!.PlayPile.AddInternal(playCard,-1);
        for(int i=0;i<4;i++) await NGame.Instance!.ToSignal(NGame.Instance.GetTree(),SceneTree.SignalName.ProcessFrame);
        PlayerCombatState pcs=player.PlayerCombatState!;
        var first=TaskCardValueNotificationProof.Capture(pcs);
        if(!first.Certified||first.Cards!=5||first.EnchantedCards!=3||first.EmptyBindings.Length!=3)
            throw new InvalidOperationException("Positive recalculation proof failed: "+JsonSerializer.Serialize(first));
        var root=CombatRootSnapshot.Capture(live);var parent=root.ForkSimulator();
        string parentBefore=DescribeContinuationContractState(parent,root,player);
        string liveBefore=ContinuationStamp.CaptureLive(live).StateText;
        var states=live.Enemies.Select(e=>CaptureActual(live,player,e)).ToArray();
        string[] fivePilesBefore=new[]{pcs.Hand,pcs.DrawPile,pcs.DiscardPile,pcs.ExhaustPile,pcs.PlayPile}
            .Select(p=>string.Join("|",p.Cards.Select(DescribeCard))).ToArray();
        string[] shadowFiveBefore=parent.State.GetPlayerCombatState(player).AllPiles
            .Select(p=>string.Join("|",p.Cards.Select(c=>DescribeCard(c.Preview)))).ToArray();
        if(!fivePilesBefore.SequenceEqual(shadowFiveBefore))
            throw new InvalidOperationException("Five-pile native/shadow root mismatch.");
        _taskCardValueUnknownCalls=0;
        var enchantments=pcs.AllCards.Select(c=>c.Enchantment).OfType<EnchantmentModel>().ToArray();
        void UnknownFinished(AbstractModel model)=>_taskCardValueUnknownCalls++;
        foreach(var enchantment in enchantments)enchantment.ExecutionFinished+=UnknownFinished;
        try
        {
            pcs.RecalculateCardValues();
            for(int i=0;i<states.Length;i++)AssertSnapshotEqual(CaptureActual(live,player,live.Enemies[i]),states[i],"CardValueRecalculate","DirectNativeNoOp");
            if(!fivePilesBefore.SequenceEqual(new[]{pcs.Hand,pcs.DrawPile,pcs.DiscardPile,pcs.ExhaustPile,pcs.PlayPile}
                .Select(p=>string.Join("|",p.Cards.Select(DescribeCard)))))
                throw new InvalidOperationException("Native no-op changed one of five ordered piles.");
            if(_taskCardValueUnknownCalls!=0||ContinuationStamp.CaptureLive(live).StateText!=liveBefore
                ||DescribeContinuationContractState(parent,root,player)!=parentBefore)
                throw new InvalidOperationException("Direct recalculation changed full state/history/RNG or dispatched ExecutionFinished.");
        }
        finally{foreach(var enchantment in enchantments)enchantment.ExecutionFinished-=UnknownFinished;}
        const BindingFlags flags=BindingFlags.Static|BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.DeclaredOnly;
        var cases=new List<object>();
        void Reject(string name,string reason)
        {
            for(int i=0;i<2;i++)
            {
                var result=TaskCardValueNotificationProof.Capture(pcs);
                if(result.Certified||result.Rejection?.Contains(reason,StringComparison.Ordinal)!=true)
                    throw new InvalidOperationException("Unknown recalculation source admitted: "+name+":"+JsonSerializer.Serialize(result));
                cases.Add(new{name,boundary=i==0?"prospective-root":"prospective-live",result,productionIntegrated=false});
            }
        }
        var harmony=new Harmony("combatsolver.testing.task-card-value-notification");
        MethodInfo prefix=typeof(UnattendedTestRunner).GetMethod(nameof(TaskCardValueUnknownPrefix),flags)!;
        var methods=new[]{AccessTools.Method(typeof(PlayerCombatState),"RecalculateCardValues"),
            AccessTools.PropertyGetter(typeof(PlayerCombatState),"AllCards"),AccessTools.PropertyGetter(typeof(PlayerCombatState),"AllPiles"),
            AccessTools.PropertyGetter(typeof(MegaCrit.Sts2.Core.Entities.Cards.CardPile),"Cards"),
            AccessTools.PropertyGetter(typeof(CardModel),"Enchantment"),AccessTools.Method(typeof(EnchantmentModel),"RecalculateValues")};
        foreach(var method in methods)
        {
            try{harmony.Patch(method,prefix:new HarmonyMethod(prefix));Reject("unknown-patch-"+method.Name,"patch:");}
            finally{harmony.Unpatch(method,HarmonyPatchType.All,harmony.Id);}
        }
        var card=pcs.PlayPile.Cards.Single();
        FieldInfo enchantmentField=typeof(CardModel).GetField("<Enchantment>k__BackingField",flags)!;
        EnchantmentModel unknown=ModelDb.DebugEnchantments.Single(e=>e.GetType()==typeof(Adroit)).ToMutable();
        enchantmentField.SetValue(card,unknown);
        try{Reject("unreviewed-native-Adroit","unreviewed-enchantment:");}
        finally{enchantmentField.SetValue(card,null);}
        Type registry=typeof(HealHook).Assembly.GetType("STS2RitsuLib.CardPiles.ModCardPileRegistry",true)!;
        FieldInfo snapshot=registry.GetField("_combatDefinitionsSnapshot",flags)!;
        object original=snapshot.GetValue(null)!;
        // A nonempty exact-typed snapshot is sufficient to refuse before any
        // definition, storage factory or custom enumerator can run.
        Array foreign=Array.CreateInstance(snapshot.FieldType.GetElementType()!,1);
        snapshot.SetValue(null,foreign);
        try{Reject("nonempty-extra-pile-snapshot","extra-combat-pile-definitions");}
        finally{snapshot.SetValue(null,original);}
        FieldInfo cache=typeof(PlayerCombatState).GetField("_piles",flags)!;
        object? originalCache=cache.GetValue(pcs);
        cache.SetValue(pcs,new[]{pcs.Hand,pcs.DrawPile,pcs.DiscardPile,pcs.ExhaustPile,pcs.PlayPile,pcs.Hand});
        try{Reject("non-native-pile-cache","non-native-pile-cache");}
        finally{cache.SetValue(pcs,originalCache);}
        var children=Enumerable.Range(0,16).Select(_=>parent.Fork()).ToArray();
        try
        {
            harmony.Patch(methods[5],prefix:new HarmonyMethod(prefix));
            await Task.WhenAll(children.Select(child=>Task.Run(()=>
            {
                using var isolation=SimulationNotificationIsolation.Enter();
                if(!first.Certified||DescribeContinuationContractState(child,root,player)!=parentBefore
                    ||DescribeContinuationContractState(child.Fork(),root,player)!=parentBefore)
                    throw new InvalidOperationException("Frozen empty-binding proof or branch changed with live patch.");
            })));
        }
        finally{harmony.Unpatch(methods[5],HarmonyPatchType.All,harmony.Id);}
        var restored=TaskCardValueNotificationProof.Capture(pcs);
        if(restored.Certified!=first.Certified||restored.Rejection!=first.Rejection||restored.Cards!=first.Cards
            ||restored.EnchantedCards!=first.EnchantedCards||restored.FutureBindingsChecked!=first.FutureBindingsChecked
            ||!restored.EmptyBindings.SequenceEqual(first.EmptyBindings)||_taskCardValueUnknownCalls!=0
            ||ContinuationStamp.CaptureLive(live).StateText!=liveBefore
            ||DescribeContinuationContractState(parent,root,player)!=parentBefore)
            throw new InvalidOperationException("Recalculation proof cleanup changed qualification or full state.");
        var output=new{first,restored,cases,unknownCalls=_taskCardValueUnknownCalls,nativeRecalculateCalls=1,
            nativeSnapshotComparisons=states.Length,fivePilesBefore,shadowFiveBefore,parallelPrecreatedChildren=16,
            noExecutionFinishedFromDirectNativeCall=true,parentLiveFullStateHistoryRngUnchanged=true,
            futureBindingScope=new[]{"Slither","Inky","Instinct"},wholeFutureSourceClosure=false,
            wholeHealthEventCertificate=false,productionIntegrated=false,productionPrunes=0,searchStarted=false};
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/card-value-notification-proof-20261008/native-details.json",JsonSerializer.Serialize(output,new JsonSerializerOptions{WriteIndented=true}));
        _completedChecks.Add("TaskCardValueProof:FivePiles:ThreeInheritedEmptyBindings:DirectNativeNoOpFullState:NoFinishedCallback:UnknownPatchesAndNativeOverrideAndPilesRejected:16FrozenForks:ResearchOnly");
    }
}

