		string modId = _modId;
		ModCardPileScope scope = spec.Scope;
		ModCardPileUiStyle style = spec.Style;
		ModCardPileAnchor anchor = spec.Anchor;
		string? iconPath = spec.IconPath;
		string[]? hotkeys = spec.Hotkeys;
		int cardShouldBeVisible;
		if (!spec.CardShouldBeVisible)
		{
			if ((object)spec != null && spec.Style == ModCardPileUiStyle.ExtraHand)
			{
