	private static void RebuildDefinitionSnapshotsLocked()
	{
		ModCardPileDefinition[] array = Definitions.Values.OrderBy<ModCardPileDefinition, string>((ModCardPileDefinition definition) => definition.Id, StringComparer.Ordinal).ToArray();
		Volatile.Write(ref _definitionsSnapshot, array);
		Volatile.Write(ref _combatDefinitionsSnapshot, array.Where((ModCardPileDefinition definition) => definition.Scope == ModCardPileScope.CombatOnly).ToArray());
	}

	private void EnsureMutable(string operation)
	{
		if (!IsFrozen)
		{
			return;
		}
		throw new InvalidOperationException($"Cannot {operation} after pile registration has been frozen ({_freezeReason ?? "unknown"}). " + "Register piles from your mod initializer before model initialization.");
	}

	private static string NormalizeId(string id)
	{
		return id.Trim();
	}
